	var x, y int64
	fmt.Scan(&n, &x, &y)
	dp := make([]int64, 2*n+1)
	dp[1] = x;
	for i := 2; i <= n; i++ {
		dp[i] = min(dp[i-1]+x, dp[(i+1)/2]+y+int64(i%2)*x)
		dp[i-1] = min(dp[i-1], dp[i]+x)
	}

	fmt.Println(dp[n])
}

